import{_ as t,o as s,c as e,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph Performance Meeting 2018-11-29","description":"","frontmatter":{"title":"Ceph Performance Meeting 2018-11-29","date":"2018-11-29T00:00:00.000Z","updated":"2018-12-01T00:00:00.000Z","tags":["Ceph","分布式存储","性能优化","CRUSH 算法","高可用性","可伸缩性"],"categories":["会议纪要"],"outline":"deep"},"headers":[],"relativePath":"posts/2018/Ceph_Performance_Meeting_2018-11-29.md","filePath":"posts/2018/Ceph_Performance_Meeting_2018-11-29.md","lastUpdated":1780460162000}'),n={name:"posts/2018/Ceph_Performance_Meeting_2018-11-29.md"};function i(l,r,g,a,p,f){return s(),e("div",null,[...r[0]||(r[0]=[o('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2018年11月29日</p><p><strong>参会人员</strong>： Greg, Mark, Sage, Erratic, George, Radek 等</p><p><strong>会议主题</strong>： Ceph 分布式存储项目进展及讨论</p><p><strong>关键细节</strong>：</p><ul><li><strong>会议开始</strong>： 由于 Mark 的麦克风问题，会议开始时未能听到其声音，后来问题解决。</li><li><strong>两周工作进展</strong>： 会议回顾了过去两周的 Pull Requests (PRs)，并讨论了合并的 PRs。</li><li><strong>PG 状态统计</strong>： 讨论了 PG 状态统计的合并情况，尽管某些 PR 已合并，但仍有部分 PR 需要处理。</li><li><strong>复杂性问题</strong>： 讨论了 Ceph 中某些复杂性问题，特别是与 Buffer List 相关的性能问题。</li><li><strong>Crimson 项目</strong>： 讨论了 Crimson 项目的进展，该项目旨在简化 Ceph 的 I/O 路径，并使用 C Star 缓冲区。</li><li><strong>LVM 性能问题</strong>： 讨论了用户在 LVM 设备上部署 Ceph 时遇到性能下降的问题，可能与 XFS 和 NVMe 驱动程序有关。</li><li><strong>Buffer List 优化</strong>： 讨论了 Buffer List 的优化方案，包括减少共享行为和使用内存复制等。</li><li><strong>PG 日志恢复</strong>： 讨论了 PG 日志恢复的优化方案，包括实现不基于日志的 PG，并重构相关代码。</li></ul><p><strong>讨论的主要议题</strong>：</p><ul><li><strong>Buffer List 的复杂性问题</strong>： 会议上重点讨论了 Buffer List 的复杂性问题，包括共享行为、内存复制等。</li><li><strong>Crimson 项目的进展</strong>： 讨论了 Crimson 项目的进展，以及如何简化 Ceph 的 I/O 路径。</li><li><strong>LVM 性能问题</strong>： 讨论了用户在 LVM 设备上部署 Ceph 时遇到性能下降的问题，并提出了可能的解决方案。</li><li><strong>Buffer List 优化方案</strong>： 讨论了多种优化 Buffer List 的方案，包括减少共享行为和使用内存复制等。</li><li><strong>PG 日志恢复的优化方案</strong>： 讨论了 PG 日志恢复的优化方案，包括实现不基于日志的 PG，并重构相关代码。</li></ul><p><strong>决定的事项</strong>：</p><ul><li><strong>继续优化 Buffer List</strong>： 会议决定继续优化 Buffer List，包括减少共享行为和使用内存复制等。</li><li><strong>关注 Crimson 项目的进展</strong>： 会议决定关注 Crimson 项目的进展，并评估其对 Ceph 性能的影响。</li><li><strong>调查 LVM 性能问题的原因</strong>： 会议决定调查 LVM 性能问题的原因，并寻找可能的解决方案。</li><li><strong>重构 PG 日志恢复相关代码</strong>： 会议决定重构 PG 日志恢复相关代码，以优化性能。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li><strong>Greg</strong>： 调查 Buffer List 的优化方案，并编写相关代码。</li><li><strong>Mark</strong>： 关注 Crimson 项目的进展，并评估其对 Ceph 性能的影响。</li><li><strong>Sage</strong>： 调查 LVM 性能问题的原因，并寻找可能的解决方案。</li><li><strong>Erratic</strong>： 与其他团队成员合作，重构 PG 日志恢复相关代码。</li></ul><p><strong>备注</strong>：</p><ul><li>会议中提到了 Ceph 中的一些技术术语，如 PG、Buffer List、Crimson 等。</li><li>会议中讨论了一些开源项目的进展，如 LVM、XFS 等。</li></ul>',14)])])}const C=t(n,[["render",i]]);export{u as __pageData,C as default};
